CREATE TABLE "talescape_step" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "talescape_step_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"taleId" integer NOT NULL,
	"sceneId" integer NOT NULL,
	"pageId" integer,
	"creatorId" text NOT NULL,
	"title" text NOT NULL,
	"description" text,
	"order" integer NOT NULL,
	"readingConfig" json DEFAULT '{"animationConfig":{"ambient":{"tracks":[]},"scrolling":{"tracks":[]}},"readingLength":null,"readingLengthMode":"content"}'::json NOT NULL,
	"snapConfig" json DEFAULT '{"mode":"scroll-snap","strategy":"shared"}'::json NOT NULL,
	"actions" json DEFAULT '[]'::json NOT NULL,
	"createdAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updatedAt" timestamp with time zone
);
