INSERT INTO "talescape_step" (
	"taleId",
	"sceneId",
	"pageId",
	"creatorId",
	"title",
	"description",
	"order",
	"readingConfig",
	"snapConfig",
	"actions"
)
SELECT
	"taleId",
	"id",
	"pageId",
	"creatorId",
	COALESCE("title", 'Opening step'),
	'Generated from the pre-refactor Scene configuration.',
	0,
	"readingConfig",
	COALESCE("transitionConfig"->'snap', '{"mode":"scroll-snap","strategy":"shared"}'::json),
	'[]'::json
FROM "talescape_scene";
--> statement-breakpoint
UPDATE "talescape_tale_progress" AS progress
SET
	"lastStepId" = step."id",
	"seenStepIds" = CASE
		WHEN step."id" IS NULL THEN '{}'::integer[]
		ELSE ARRAY[step."id"]
	END
FROM "talescape_step" AS step
WHERE step."sceneId" = progress."lastSceneId" AND step."order" = 0;
